1) The bug (short)
- The builder simply renders NULLs inside IN/NOT IN as regular placeholders (e.g. col IN (1, NULL) -> "col IN (?, ?)"), which relies on SQL's comparison semantics for NULL. But SQL treats comparisons with NULL as UNKNOWN, so:
  - col IN (1, NULL) will NOT be true for rows where col IS NULL (it yields UNKNOWN).
  - col NOT IN (1, NULL) yields UNKNOWN and will filter out rows (not the intended "allow or disallow NULLs").
- When such an IN/NOT IN is nested inside OR/AND groups, the missing explicit IS NULL / IS NOT NULL parts cause logical mistakes (e.g. expecting NULL rows to be matched by an IN list containing NULL, but they won't be, or NOT IN with NULL will suppress rows).
- Desired semantics: treat Python's None as "SQL NULL" meaning "include/exclude NULL values explicitly":
  - IN with None -> (col IN (non_nulls) OR col IS NULL)
  - NOT IN with None -> (col NOT IN (non_nulls) AND col IS NOT NULL)
  - If the list contains only None -> IN -> col IS NULL ; NOT IN -> col IS NOT NULL

2) Failing test (what it demonstrates)
- Example case that previously failed: or_(in_('a', [1, None]), eq('b', 'x'))
  - Old builder produced: "SELECT * FROM t WHERE a IN (?, ?) OR b = ?" with params [1, None, 'x']
  - That's wrong: rows with a IS NULL are not matched by "a IN (1, NULL)". The correct SQL is: "SELECT * FROM t WHERE (a IN (?) OR a IS NULL) OR b = ?" with params [1, 'x'].

3 & 4) Fixed code with test function(s)
- The code below fixes _build_condition so IN/NOT IN handle None specially and produce properly parenthesized expressions that work inside nested groups.
- It includes a test function test_in_with_null_in_or() that demonstrates and validates the previously failing case. There's also test_not_in_with_null_in_and() for NOT IN with NULL.

Complete fixed code (including the test functions):

```python
"""SQL query builder with support for complex WHERE clauses. Fixed handling for IN/NOT IN with NULLs."""
from typing import Any, List, Optional, Union, Tuple
from enum import Enum
from dataclasses import dataclass, field

class Op(Enum):
    EQ = "="
    NE = "!="
    LT = "<"
    GT = ">"
    LTE = "<="
    GTE = ">="
    LIKE = "LIKE"
    IN = "IN"
    NOT_IN = "NOT IN"
    IS_NULL = "IS NULL"
    IS_NOT_NULL = "IS NOT NULL"
    BETWEEN = "BETWEEN"

@dataclass
class Condition:
    column: str
    op: Op
    value: Any = None

@dataclass
class ConditionGroup:
    conditions: List[Union['Condition', 'ConditionGroup']]
    logic: str = "AND"  # AND or OR

@dataclass
class OrderBy:
    column: str
    direction: str = "ASC"

@dataclass
class JoinClause:
    table: str
    on: str
    join_type: str = "INNER"

class QueryBuilder:
    def __init__(self, table: str):
        self.table = table
        self._select: List[str] = ["*"]
        self._where: Optional[ConditionGroup] = None
        self._order_by: List[OrderBy] = []
        self._limit: Optional[int] = None
        self._offset: Optional[int] = None
        self._joins: List[JoinClause] = []
        self._group_by: List[str] = []
        self._having: Optional[ConditionGroup] = None
        self._params: List[Any] = []

    def select(self, *columns: str) -> 'QueryBuilder':
        self._select = list(columns)
        return self

    def where(self, *conditions: Union[Condition, ConditionGroup]) -> 'QueryBuilder':
        if len(conditions) == 1 and isinstance(conditions[0], ConditionGroup):
            self._where = conditions[0]
        else:
            self._where = ConditionGroup(conditions=list(conditions), logic="AND")
        return self

    def order_by(self, column: str, direction: str = "ASC") -> 'QueryBuilder':
        self._order_by.append(OrderBy(column=column, direction=direction))
        return self

    def limit(self, n: int) -> 'QueryBuilder':
        self._limit = n
        return self

    def offset(self, n: int) -> 'QueryBuilder':
        self._offset = n
        return self

    def join(self, table: str, on: str, join_type: str = "INNER") -> 'QueryBuilder':
        self._joins.append(JoinClause(table=table, on=on, join_type=join_type))
        return self

    def group_by(self, *columns: str) -> 'QueryBuilder':
        self._group_by = list(columns)
        return self

    def having(self, *conditions: Union[Condition, ConditionGroup]) -> 'QueryBuilder':
        if len(conditions) == 1 and isinstance(conditions[0], ConditionGroup):
            self._having = conditions[0]
        else:
            self._having = ConditionGroup(conditions=list(conditions), logic="AND")
        return self

    def build(self) -> Tuple[str, List[Any]]:
        self._params = []
        parts = [f"SELECT {', '.join(self._select)}"]
        parts.append(f"FROM {self.table}")

        for j in self._joins:
            parts.append(f"{j.join_type} JOIN {j.table} ON {j.on}")

        if self._where:
            where_sql = self._build_condition_group(self._where)
            parts.append(f"WHERE {where_sql}")

        if self._group_by:
            parts.append(f"GROUP BY {', '.join(self._group_by)}")

        if self._having:
            having_sql = self._build_condition_group(self._having)
            parts.append(f"HAVING {having_sql}")

        if self._order_by:
            order_parts = [f"{o.column} {o.direction}" for o in self._order_by]
            parts.append(f"ORDER BY {', '.join(order_parts)}")

        if self._limit is not None:
            parts.append(f"LIMIT {self._limit}")

        if self._offset is not None:
            parts.append(f"OFFSET {self._offset}")

        return " ".join(parts), self._params

    def _build_condition_group(self, group: ConditionGroup) -> str:
        parts = []
        for cond in group.conditions:
            if isinstance(cond, ConditionGroup):
                sub = self._build_condition_group(cond)
                parts.append(f"({sub})")
            elif isinstance(cond, Condition):
                parts.append(self._build_condition(cond))
        return f" {group.logic} ".join(parts)

    def _build_condition(self, cond: Condition) -> str:
        if cond.op == Op.IS_NULL:
            return f"{cond.column} IS NULL"
        if cond.op == Op.IS_NOT_NULL:
            return f"{cond.column} IS NOT NULL"
        if cond.op == Op.BETWEEN:
            # Expect value to be iterable with two items
            low_high = list(cond.value)
            if len(low_high) != 2:
                raise ValueError("BETWEEN requires a two-element value")
            self._params.extend(low_high)
            return f"{cond.column} BETWEEN ? AND ?"
        if cond.op in (Op.IN, Op.NOT_IN):
            values = cond.value if isinstance(cond.value, (list, tuple)) else [cond.value]
            # Split out NULLs (Python None) from non-null values
            non_null_vals = [v for v in values if v is not None]
            has_null = any(v is None for v in values)

            # Handle combinations:
            # - non-null values only: normal IN/NOT IN with placeholders
            # - non-null + NULL: add explicit IS NULL / IS NOT NULL
            # - NULLs only: IS NULL / IS NOT NULL
            # - empty list: choose a safe representation (IN -> false, NOT IN -> true)
            if non_null_vals and has_null:
                placeholders = ", ".join("?" for _ in non_null_vals)
                if cond.op == Op.IN:
                    # (col IN (non_null_vals) OR col IS NULL)
                    self._params.extend(non_null_vals)
                    return f"({cond.column} IN ({placeholders}) OR {cond.column} IS NULL)"
                else:
                    # (col NOT IN (non_null_vals) AND col IS NOT NULL)
                    self._params.extend(non_null_vals)
                    return f"({cond.column} NOT IN ({placeholders}) AND {cond.column} IS NOT NULL)"
            elif non_null_vals and not has_null:
                placeholders = ", ".join("?" for _ in non_null_vals)
                self._params.extend(non_null_vals)
                op_str = "IN" if cond.op == Op.IN else "NOT IN"
                return f"{cond.column} {op_str} ({placeholders})"
            elif not non_null_vals and has_null:
                # Only NULL(s) in the list -> IS NULL or IS NOT NULL
                if cond.op == Op.IN:
                    return f"{cond.column} IS NULL"
                else:
                    return f"{cond.column} IS NOT NULL"
            else:
                # Empty list case:
                # - IN () is always false -> represent as 0=1
                # - NOT IN () is always true -> represent as 1=1
                if cond.op == Op.IN:
                    return "0=1"
                else:
                    return "1=1"

        # default binary ops
        self._params.append(cond.value)
        return f"{cond.column} {cond.op.value} ?"


# Helper functions
def and_(*conditions) -> ConditionGroup:
    return ConditionGroup(conditions=list(conditions), logic="AND")

def or_(*conditions) -> ConditionGroup:
    return ConditionGroup(conditions=list(conditions), logic="OR")

def eq(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.EQ, value=val)

def ne(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.NE, value=val)

def lt(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.LT, value=val)

def gt(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.GT, value=val)

def in_(col: str, vals: List[Any]) -> Condition:
    return Condition(column=col, op=Op.IN, value=vals)

def not_in(col: str, vals: List[Any]) -> Condition:
    return Condition(column=col, op=Op.NOT_IN, value=vals)

def is_null(col: str) -> Condition:
    return Condition(column=col, op=Op.IS_NULL)

def between(col: str, low: Any, high: Any) -> Condition:
    return Condition(column=col, op=Op.BETWEEN, value=[low, high])


# --- Tests that demonstrate the bug and verify the fix ---

def test_in_with_null_in_or():
    """
    Previously this would produce:
      SELECT * FROM t WHERE a IN (?, ?) OR b = ?
      params: [1, None, 'x']
    which does not match rows where a IS NULL.
    Correct output should explicitly include IS NULL and not include None in params:
      SELECT * FROM t WHERE (a IN (?) OR a IS NULL) OR b = ?
      params: [1, 'x']
    """
    qb = QueryBuilder("t").where(or_(in_("a", [1, None]), eq("b", "x")))
    sql, params = qb.build()

    expected_sql = "SELECT * FROM t WHERE (a IN (?) OR a IS NULL) OR b = ?"
    expected_params = [1, "x"]
    assert sql == expected_sql, f"SQL mismatch: got {sql!r}, want {expected_sql!r}"
    assert params == expected_params, f"Params mismatch: got {params!r}, want {expected_params!r}"

def test_not_in_with_null_in_and():
    """
    NOT IN with NULL should become:
      (a NOT IN (non_null) AND a IS NOT NULL)
    """
    qb = QueryBuilder("t").where(and_(not_in("a", [1, None]), eq("b", "x")))
    sql, params = qb.build()

    expected_sql = "SELECT * FROM t WHERE (a NOT IN (?) AND a IS NOT NULL) AND b = ?"
    expected_params = [1, "x"]
    assert sql == expected_sql, f"SQL mismatch: got {sql!r}, want {expected_sql!r}"
    assert params == expected_params, f"Params mismatch: got {params!r}, want {expected_params!r}"

if __name__ == "__main__":
    # Run tests
    test_in_with_null_in_or()
    test_not_in_with_null_in_and()
    print("All tests passed.")
